def reverse_pairs(nums):
    n = len(nums)
    return sum(1 for i in range(n) for j in range(i + 1, n) if nums[i] > 2 * nums[j])

def reverse_pairs(nums):
    def sort(a):
        if len(a) <= 1:
            return a, 0
        mid = len(a) // 2
        left, cl = sort(a[:mid])
        right, cr = sort(a[mid:])
        count, j = cl + cr, 0
        for x in left:
            while j < len(right) and x > 2 * right[j]:
                j += 1
            count += j
        return sorted(left + right), count

    return sort(nums)[1]

def reverse_pairs(nums):
    vals = sorted(set(nums))
    tree = [0] * (len(vals) + 1)

    def add(i):
        while i < len(tree):
            tree[i] += 1
            i += i & -i

    def prefix(i):
        s = 0
        while i > 0:
            s += tree[i]
            i -= i & -i
        return s

